   FROM main_marts.fact_orders AS m
   WHERE m.ordered_at >= timezone('Asia/Ho_Chi_Minh', CAST(CAST(date_trunc('month', (CAST(timezone('Asia/Ho_Chi_Minh', now()) AS DATE) - 1)) AS DATE) AS TIMESTAMP))
     AND m.ordered_at < timezone('Asia/Ho_Chi_Minh', CAST((CAST(timezone('Asia/Ho_Chi_Minh', now()) AS DATE) - 1) AS TIMESTAMP))
     AND m.scope_sales
